package com.hospital.smartqueue.doctor.domain; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="doctors") public class Doctor{@Id private UUID id; @Column(name="hospital_id") private UUID hospitalId; private String doctorCode,name,specialization,professionalRegistrationNumber; @Enumerated(EnumType.STRING) private Status status; public enum Status{ACTIVE,INACTIVE} protected Doctor(){} public Doctor(UUID i,UUID h,String c,String n,String s,String r,Status st){id=i;hospitalId=h;doctorCode=c;name=n;specialization=s;professionalRegistrationNumber=r;status=st;} public UUID getId(){return id;} public UUID getHospitalId(){return hospitalId;} public Status getStatus(){return status;} public void setStatus(Status s){status=s;}}
